using System.IO;
using UnityEditor;

namespace Palace.EditorTools
{
    /// <summary>
    /// The painted art (tables, cards, cosmetics and the country flags) is generated by
    /// Palace > Setup > 2 - Generate Art. If it hasn't been run yet, or is out of date (no flags),
    /// this offers to run it when the project opens, so nobody plays with missing cosmetics.
    /// Asks once per Unity session.
    /// </summary>
    [InitializeOnLoad]
    public static class PalaceArtCheck
    {
        private const string AskedKey = "Palace.ArtCheckAsked";

        static PalaceArtCheck()
        {
            if (UnityEngine.Application.isBatchMode) return;
            EditorApplication.delayCall += Check;
        }

        private static void Check()
        {
            if (SessionState.GetBool(AskedKey, false) || EditorApplication.isPlayingOrWillChangePlaymode) return;
            SessionState.SetBool(AskedKey, true);

            bool library = File.Exists(PalaceArtGenerator.LibraryPath);
            bool flags = File.Exists(PalaceArtGenerator.ArtFolder + "/flag_back_chile.png"); // the newest flags
            bool premium = File.Exists(PalaceArtGenerator.ArtFolder + "/premium_back_holo.png");
            if (library && flags && !premium)
            {
                // Only the premium range is new: paint just that (much quicker than everything).
                if (EditorUtility.DisplayDialog("Palace: add the premium range?",
                        "New premium card backs, decks and tables are ready to paint (a minute or two).", "Paint them", "Later"))
                    PalacePremiumArt.RegenerateMenu();
                return;
            }
            if (library && flags)
            {
                var lib = AssetDatabase.LoadAssetAtPath<CosmeticLibrary>(PalaceArtGenerator.LibraryPath);

                // Tables still referenced the old way (all loaded at once): move them to load on demand.
                if (lib != null && lib.tables.Exists(t => t.table != null) &&
                    EditorUtility.DisplayDialog("Palace: make tables load on demand?",
                        "The table images can now load only when they're used, which saves a lot of memory on phones. " +
                        "Organise them now? (under a minute; nothing changes in how the game looks)", "Organise", "Later"))
                {
                    PalaceTableStore.OrganiseMenu();
                    return;
                }

                // Only the name fonts are missing: that's quick to fix on its own.
                if (lib != null && lib.fonts.Count <= 1 &&
                    EditorUtility.DisplayDialog("Palace: add the name fonts?",
                        "New name fonts are ready to add to the Customise screen (a few seconds).", "Add them", "Later"))
                    PalaceNameFonts.RebuildMenu();
                return;
            }

            bool go = EditorUtility.DisplayDialog("Palace: generate the art?",
                "The painted art hasn't been generated yet (or is missing the newest items, such as the country flags).\n\n" +
                "Without it the table is plain and the Customise screen is empty.\n\n" +
                "Generate it now? It takes a few minutes (there are 42 flag tables to paint).",
                "Generate now", "Later");
            if (go) PalaceArtGenerator.GenerateAll();
        }
    }
}
